// ====================================================
// Preparar Contexto para IA — G54 Field Mapping
// G54 API fields:
//   company: name, description, value_proposition, base_city, website, emails[], phones[]
//   products: name, description, keywords[]
//   ideas: id, topic, keyword, platform, description
//   estrategia: objetivo, audiencia, tono, cta_principal, embudo, pilares[]
// ====================================================

const empresaRaw = $('📊 Obtener Perfil Empresa').item.json;
// G54 wraps in .data, Airtable uses .fields
const empresa = empresaRaw.data || empresaRaw.fields || empresaRaw || {};

const productosRaw = $('📦 Obtener Servicios Activos').item.json;
// G54: { company_id, data: [{id, name, description, keywords[]}] }
const productosData = productosRaw.data || productosRaw.items || productosRaw.records || (Array.isArray(productosRaw) ? productosRaw : []);

// G54 ideas response: { data: [{id, topic, keyword, platform, description}] }
const temaRaw = $('📅 Obtener Próximo Tema Semanal').item.json;
const temaList = temaRaw.data || temaRaw.items || temaRaw.records || (Array.isArray(temaRaw) ? temaRaw : [temaRaw]);
const temaItem = (Array.isArray(temaList) ? temaList[0] : temaList) || {};
const tema = temaItem.fields || temaItem || {};
const temaId = temaItem.id || temaItem.social_idea_id || temaItem.tema_id || null;

// Estrategia (continueOnFail — null if not configured yet)
const estRaw = $('🎯 Obtener Estrategia RRSS').item?.json || {};
const estrategia = estRaw.data || estRaw || {};

// Build product/service summary — handles G54 (name/description) and Airtable fallback
const servicios = productosData
  .filter(p => (p.fields || p).is_active !== false)
  .map(p => {
    const f = p.fields || p;
    const nombre = f.name || f.nombre || f['Nombre de Servicio'] || '';
    const desc   = f.description || f.descripcion || f['Descripción comercial'] || '';
    const kws    = Array.isArray(f.keywords) ? f.keywords.slice(0,3).join(', ') : '';
    return `- ${nombre}: ${desc}${kws ? ' [' + kws + ']' : ''}`.slice(0, 220);
  })
  .join('\n');

return [{
  json: {
    // ---- Empresa (G54 field names first, Airtable fallback) ----
    empresa_nombre:          empresa.name || empresa.nombre_empresa || empresa['\ufeffnombre_empresa'] || 'Crating Express',
    empresa_descripcion:     empresa.description || empresa.descripcion_corta || '',
    empresa_propuesta_valor: empresa.value_proposition || empresa.propuesta_valor || '',
    empresa_ciudad:          empresa.base_city || empresa.ciudad_base || empresa['ciudad base'] || 'Miami, FL',
    empresa_web:             empresa.website || empresa.sitio_web || 'cratingexpress.com',
    empresa_telefono:        (empresa.phones || [])[0] || empresa.telefono || '',
    empresa_email:           (empresa.emails || [])[0] || 'cratingexpress01@gmail.com',
    empresa_geografia:       empresa.geography || empresa.coverage || 'Miami / South Florida',
    empresa_competidores:    (empresa.competitors_known || []).slice(0,3).map(c => c.name).join(', '),
    servicios_resumen:       servicios,
    // ---- Tema / Idea G54 ----
    tema_id:                 temaId,
    tema_texto:              tema.topic || tema.tema || tema['Tema'] || '',
    tema_descripcion:        tema.description || tema.descripcion || tema['Descripcion'] || '',
    tema_palabras_clave:     (Array.isArray(tema.keywords) ? tema.keywords.join(', ') : tema.keywords) || tema.keyword || tema.palabras_clave || '',
    keyword_principal:       tema.keyword || tema.keyword_principal || tema['Keyword_Principal'] || '',
    tema_semana:             tema.week || tema.semana || tema['Semana'] || 0,
    tema_plataforma:         tema.platform || tema.plataforma || 'Instagram',
    fecha_post:              new Date().toLocaleDateString('es-US', {timeZone: 'America/New_York'}),
    // ---- Estrategia G54 ----
    estrategia_objetivo:     estrategia.objetivo || estrategia.primary_goal || empresa.primary_goal || '',
    estrategia_audiencia:    estrategia.audiencia || estrategia.target_market || empresa.target_market || '',
    estrategia_tono:         estrategia.tono || 'profesional, directo y humano',
    estrategia_cta:          estrategia.cta_principal || 'Solicitar cotización: cratingexpress.com/request-a-quote/',
    estrategia_embudo:       estrategia.embudo || 'TOFU-MOFU',
    estrategia_pilares:      Array.isArray(estrategia.pilares) ? estrategia.pilares.join(', ') : (estrategia.pilares || 'embalaje industrial, exportación, logística Miami'),
    // ---- Imagen (G54 provee la URL — subida por usuario o generada por Image AI) ----
    imagen_url:              tema.imagen_url || tema.image_url || null,
    imagen_specs:            tema.imagen_specs || tema.image_specs || '',
  }
}];

const aiResponse = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || $input.item.json.choices?.[0]?.message?.content || '{}';
let post;
try {
  post = JSON.parse(aiResponse);
} catch(e) {
  const match = aiResponse.match(/\{[\s\S]*\}/);
  post = match ? JSON.parse(match[0]) : {};
}

const contexto = $('🔧 Preparar Contexto para IA').item.json;

// Normalizar hashtags: array → string
const rawHashtags = post.hashtags || '';
const hashtags = Array.isArray(rawHashtags) ? rawHashtags.join(' ') : rawHashtags;

// Garantizar URL en el CTA (por si Groq no lo incluye)
const QUOTE_URL = 'cratingexpress.com/request-a-quote/';
let cta = post.cta || '';
if (!cta.includes('cratingexpress.com') && !cta.includes('http')) {
  cta = cta.trim() + ' → ' + QUOTE_URL;
}

return [{
  json: {
    ...contexto,
    hook_es: post.hook || '',
    mensaje_es: post.mensaje || '',
    cta_es: cta,
    hashtags: hashtags,
    texto_canva_titulo: post.texto_canva_titulo || '',
    texto_canva_subtitulo: post.texto_canva_subtitulo || ''
  }
}];

const aiResponse = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text
  || $input.item.json.choices?.[0]?.message?.content || '{}';

let versiones;
try { versiones = JSON.parse(aiResponse); }
catch(e) {
  const m = aiResponse.match(/\{[\s\S]*\}/);
  versiones = m ? JSON.parse(m[0]) : {};
}

const prevData = $('🔍 Parsear Post Español').item.json;

// ── Array → paragraph string ───────────────────────────────────────────────
function fromArray(arr) {
  if (Array.isArray(arr) && arr.length > 0)
    return arr.map(p => p.trim()).filter(p => p.length > 0).join('\n\n');
  return null;
}

// ── Smart split for plain text ─────────────────────────────────────────────
function smartSplit(text, spp) {
  if (!text) return '';
  text = text.trim();
  const hashIdx = text.search(/(^|\s)#\w/);
  let body = hashIdx > 0 ? text.slice(0, hashIdx).trim() : text;
  const tags = hashIdx > 0 ? text.slice(hashIdx).trim() : '';
  const sentences = body.match(/[^.!?]+[.!?]+/g) || [body];
  const paragraphs = [];
  for (let i = 0; i < sentences.length; i += spp) {
    const chunk = sentences.slice(i, i + spp).join(' ').trim();
    if (chunk) paragraphs.push(chunk);
  }
  if (tags) paragraphs.push(tags);
  return paragraphs.join('\n\n');
}

// ── Instagram split ─────────────────────────────────────────────────────────
function splitInstagram(arr, text) {
  const joined = fromArray(arr);
  if (joined) return joined;
  if (!text) return '';
  text = text.trim();
  const hashIdx = text.search(/(^|\s)#\w/);
  const tags = hashIdx > 0 ? text.slice(hashIdx).trim() : '';
  const body = hashIdx > 0 ? text.slice(0, hashIdx).trim() : text;
  const lines = body.split(/\s{2,}|\n/).map(l => l.trim()).filter(l => l);
  const ctaIdx = lines.findIndex(l => /cratingexpress|free|visit|request|link in bio/i.test(l));
  let parts = [];
  if (ctaIdx > 0) {
    parts.push(lines.slice(0, ctaIdx).join(' '));
    parts.push(lines.slice(ctaIdx).join(' '));
  } else {
    const mid = Math.ceil(lines.length / 2);
    parts.push(lines.slice(0, mid).join(' '));
    if (lines.slice(mid).length) parts.push(lines.slice(mid).join(' '));
  }
  if (tags) parts.push(tags);
  return parts.filter(p => p).join('\n\n');
}

// ── Hashtag enforcement ────────────────────────────────────────────────────
function enforceHashtags(raw, count, required, pool) {
  const found = (raw || '').match(/#[A-Za-z0-9_]+/g) || [];
  const seen = new Set();
  const final = [];
  required.forEach(function(h) { if (!seen.has(h)) { seen.add(h); final.push(h); } });
  found.forEach(function(h)    { if (!seen.has(h) && final.length < count) { seen.add(h); final.push(h); } });
  for (let i = 0; i < pool.length && final.length < count; i++) {
    if (!seen.has(pool[i])) { seen.add(pool[i]); final.push(pool[i]); }
  }
  return final.slice(0, count).join(' ');
}

const FB_POOL = ['#WoodCrating','#CustomCrating','#MiamiLogistics','#IndustrialPackaging',
  '#FreightProtection','#ShippingExperts','#WoodPackaging','#ExportCrating'];
const IG_POOL = ['#packaging','#logistics','#shipping','#manufacturing','#miami',
  '#woodpackaging','#customcrating','#industrialpackaging','#woodencrates','#freightprotection',
  '#woodcrating','#exportcrating','#cratingexpress','#miamilogistics','#exportpackaging'];

const fbHashtags = enforceHashtags(versiones.facebook_hashtags, 5, ['#ISPM15'], FB_POOL);
const igHashtags = enforceHashtags(versiones.instagram_hashtags, 13, ['#ISPM15'], IG_POOL);

const fbBody = fromArray(versiones.facebook_paragraphs) || smartSplit(versiones.facebook, 2) || '';
const igBody = splitInstagram(versiones.instagram_lines, versiones.instagram) || '';

const fbClean = fbBody.replace(/#[A-Za-z0-9_]+/g, '').replace(/\n{3,}/g, '\n\n').trim();
const igClean = igBody.replace(/#[A-Za-z0-9_]+/g, '').replace(/\n{3,}/g, '\n\n').trim();

// ── UTM Tracking ─────────────────────────────────────────────────────────────
function addUtm(text, source, medium, campaign) {
  if (!text) return text;
  return text.replace(
    /https?:\/\/(www\.)?cratingexpress\.com(\/[^\s"'<>\)]*)?/g,
    function(match) {
      if (match.includes('utm_source')) return match;
      const sep = match.includes('?') ? '&' : '?';
      return match + sep + 'utm_source=' + source +
             '&utm_medium=' + medium + '&utm_campaign=' + campaign;
    }
  );
}

return [{
  json: {
    ...prevData,
    texto_canva_titulo_en:    versiones.texto_canva_titulo_en    || prevData.texto_canva_titulo   || '',
    texto_canva_subtitulo_en: versiones.texto_canva_subtitulo_en || prevData.texto_canva_subtitulo || '',
    post_facebook_en:  addUtm(fbClean + '\n\n' + fbHashtags, 'facebook',  'social', 'rrss-automation'),
    post_instagram_en: addUtm(igClean + '\n\n' + igHashtags, 'instagram', 'social', 'rrss-automation'),
  }
}];

const estructura = $input.first().json;
const parsear = $('🔍 Parsear Versiones Inglés').item.json;
const wpItem = $('🖼️ Obtener URL de Imagen').first().json;
const presentacionId = $('📋 Slides: Copiar Template').item.json.id;

const slideId = estructura.slides?.[0]?.objectId || 'p1';
const pageElements = estructura.slides?.[0]?.pageElements || [];

const wpImageUrl = wpItem?.imagen_url || null;
const titulo = parsear.texto_canva_titulo_en || parsear.texto_canva_titulo || 'Post Title';

// TEXT requests
const textRequests = [
  { replaceAllText: { containsText: { text: '[titulo_post]', matchCase: true }, replaceText: titulo } },
  { replaceAllText: { containsText: { text: '[descripcion_post]', matchCase: true }, replaceText: parsear.texto_canva_subtitulo_en || parsear.texto_canva_subtitulo || 'Post description' } }
];

const titleShape = pageElements.find(el =>
  (el.shape?.text?.textElements || []).some(te => (te.textRun?.content || '').includes('[titulo_post]'))
);
if (titleShape) {
  let fontSize = 52;
  if (titulo.length > 15) fontSize = 40;
  if (titulo.length > 22) fontSize = 32;
  if (titulo.length > 30) fontSize = 26;
  textRequests.push({
    updateTextStyle: {
      objectId: titleShape.objectId,
      textRange: { type: 'ALL' },
      style: { fontSize: { magnitude: fontSize, unit: 'PT' } },
      fields: 'fontSize'
    }
  });
}

// IMAGE: use replaceImage on the existing image element in the template
let imageRequest = null;
if (wpImageUrl) {
  const imageElement = pageElements.find(el => el.image !== undefined);
  if (imageElement) {
    imageRequest = {
      requests: [{
        replaceImage: {
          imageObjectId: imageElement.objectId,
          url: wpImageUrl,
          imageReplaceMethod: 'CENTER_CROP'
        }
      }]
    };
  }
}

return [{ json: { presentacionId, textRequests, imageRequest, wpImageUrl, titulo, subtitulo: parsear.texto_canva_subtitulo } }];
